arguments.cmd:
python3 - <<'EOF'
import os
root='/challenge/inhere'
for dp,dns,fns in os.walk(root):
    for n in dns+fns:
        p=os.path.join(dp,n)
        try:
            x=os.listxattr(p)
            if x:
                print("XATTR",p,[(k,os.getxattr(p,k)) for k in x])
        except Exception as e:
            print("ERR",p,e)
print("done")
EOF

